// Official AT&T header icon paths, transcribed from att.com's mega-nav markup.
// The nav-category icons use `.svg-base` (ink) so they inherit the same treatment
// att.com gives them; the right-hand utility icons carry their own fills because
// att.com ships them with literal #1D2329 / #686E74 values.

type P = { className?: string };

const base = "h-5 w-5 shrink-0";

export function ShopIcon({ className = "" }: P) {
  return (
    <svg viewBox="0 0 32 32" className={`${base} ${className}`} aria-hidden="true">
      <path
        fill="#1D2329"
        d="M22 8V7a6 6 0 00-12 0v1H4v20a3 3 0 003 3h18a3 3 0 003-3V8zM12 7a4 4 0 018 0v1h-8zm14 21a1 1 0 01-1 1H7a1 1 0 01-1-1V10h4v4h2v-4h8v4h2v-4h4z"
      />
    </svg>
  );
}

